const fs = require('fs');
const path = require('path');

/**
 * Inlines the GDJS runtime "index.html" template into a JS module
 * (src/GameEngineFinder/BundledRuntimeTemplate.js) so the preview pipeline
 * can start without ANY network request — even inside the offline Android
 * APK where fetching local assets through window.fetch is unreliable.
 *
 * Run automatically as part of "npm run import-resources" (see package.json).
 */
const candidates = [
  // Prefer the built runtime (populated by import-GDJS-Runtime.js):
  path.join(__dirname, '..', 'resources', 'GDJS', 'Runtime', 'index.html'),
  // Fall back to the runtime source in the repository:
  path.join(__dirname, '..', '..', '..', 'GDJS', 'Runtime', 'index.html'),
];

const templatePath = candidates.find(candidate => fs.existsSync(candidate));
if (!templatePath) {
  console.error(
    'generate-bundled-runtime-template.js: no GDJS Runtime index.html found in:',
    candidates.join(' | ')
  );
  process.exit(1);
}

const content = fs.readFileSync(templatePath, 'utf8');
if (!content.includes('<!-- GDJS_CODE_FILES -->')) {
  console.error(
    'generate-bundled-runtime-template.js: the template looks invalid (missing GDJS_CODE_FILES marker).'
  );
  process.exit(1);
}

const outPath = path.join(
  __dirname,
  '..',
  'src',
  'GameEngineFinder',
  'BundledRuntimeTemplate.js'
);
const moduleSource = `// @flow
// AUTO-GENERATED by scripts/generate-bundled-runtime-template.js — do not edit.
// The GDJS runtime index.html template, inlined into the bundle so previews
// can be prepared with zero network requests (offline / Android APK).

export const BUNDLED_RUNTIME_INDEX_HTML = ${JSON.stringify(content)};
`;

fs.writeFileSync(outPath, moduleSource);
console.log(
  `BundledRuntimeTemplate.js written from ${templatePath} (${content.length} chars).`
);
